from pathlib import Path
import re

root = Path(__file__).resolve().parent.parent
source = (root/'reference/JFK Airfield Agents.html').read_text()

(root/'reference/JFK Airfield Agents.html').write_text(source)
styles = '\n'.join(re.findall(r'<style>(.*?)</style>', source, re.S))
script = re.search(r'<script>(.*?)</script>', source, re.S).group(1)
html = re.sub(r'<style>.*?</style>', '', source, flags=re.S)
html = re.sub(r'<link[^>]*>', '', html)
html = re.sub(r'<script>.*?</script>', '', html, flags=re.S)
html = html.replace('</head>', '<link rel="stylesheet" href="/jfk-base.css"><link rel="stylesheet" href="/jfk-connected.css"></head>')
demo = html.replace('</body>', '<script src="/jfk-demo.js"></script></body>')
demo = demo.replace('<h1>Airfield Agents <span>· ground &amp; runway deconfliction</span></h1>', '<h1>Original airfield demo <span>· local policy simulation</span></h1>')
demo = demo.replace('<span class="cfg">ARR 4R · 13L &nbsp; DEP 4L · 13R</span>', '<span class="cfg">Standalone simulation · not a Clearance plan · no LLM calls</span>')
(root/'public/jfk-demo.html').write_text(demo)
(root/'public/jfk-demo.js').write_text(script)
(root/'public/jfk-base.css').write_text(styles)

plan = html.replace('<h1>Airfield Agents <span>· ground &amp; runway deconfliction</span></h1>', '<h1>JFK surface coordination <span>· Clearance plan replay</span></h1>')
plan = plan.replace('06:40:00', '14:00:00').replace('<span class="cfg">ARR 4R · 13L &nbsp; DEP 4L · 13R</span>', '<span class="cfg" id="planState">WAITING FOR CLEARANCE</span>')
plan = plan.replace('>Pause</button>', ' disabled>Play plan</button>')
plan = plan.replace('>1×</button>', '>1 min/s</button>').replace('>2×</button>', '>2 min/s</button>').replace('>4×</button>', '>4 min/s</button>')
plan = plan.replace('id="surge" type="button">Surge arrivals', 'id="surge" type="button">Run negotiation')
plan = plan.replace('id="inject" type="button">Inject runway incursion', 'id="inject" type="button">Tug 2 offline')
plan = plan.replace('<input type="checkbox" id="ovPred" checked><span>Predictions</span>', '<input type="checkbox" id="ovPred" checked><span>Gate status</span>')
plan = plan.replace('JFK airfield with live aircraft', 'JFK schematic with aircraft positions replayed from the Clearance plan')
plan = plan.replace('Tower · runways', 'ATC · runway slots').replace('Ground · taxi', 'Ground · gates & taxi').replace('Sentinel · 4 s prediction', 'Pilot · fuel margins').replace('Conflict</span>', 'Constraint finding</span>')
plan = plan.replace('TOWER<small>runway clearances &amp; sequencing</small>', 'ATC<small>runway slots &amp; surface capacity</small>')
plan = plan.replace('SENTINEL<small>conflict prediction &amp; incursions</small>', 'PILOT<small>departure fuel &amp; readiness</small>')
plan = plan.replace('agSEN','agPILOT').replace('nSEN','nPILOT').replace('lSEN','lPILOT')
plan = plan.replace('Click an aircraft to follow it', 'Click an aircraft or flight strip to inspect its plan')
plan = plan.replace('<section>\n        <h2>Runways</h2>', '<section><h2>Selected plan</h2><p id="planSummary" class="plan-summary">Run the negotiation to create a plan. Aircraft start at their simulated stands.</p></section>\n      <section>\n        <h2>Runways</h2>')
plan = plan.replace('</svg>', '<g id="gStands"></g><g id="gResources"></g></svg>',1)
plan = plan.replace('<div class="hint">', '<div class="map-tools"><button class="btn" id="zoomIn" aria-label="Zoom in">+</button><button class="btn" id="zoomOut" aria-label="Zoom out">−</button><button class="btn" id="zoomFit">Fit</button></div><div class="map-source">JFK-inspired schematic · illustrative taxi graph · stand assignments simulated</div><div class="hint">')
plan = plan.replace('    </div>\n\n    <aside>', '      <div class="replay"><button class="btn" id="rewind" title="Return to start">↺</button><span id="replayClock">14:00</span><input id="replayTime" aria-label="Plan replay time" type="range" min="0" max="60" step="0.1" value="0" disabled><span id="replayEnd">15:00</span><span class="replay-note">REPLAY ONLY</span></div>\n    </div>\n\n    <aside>',1)
plan = plan.replace('</body>', '<script type="module" src="/jfk-plan.js"></script></body>')
(root/'public/jfk-plan.html').write_text(plan)
prefix = script.split('/* ---------- Simulation state ---------- */')[0].replace('(()=>{\n','',1)
prefix = prefix.replace('>1 km</text>', '>SCHEMATIC</text>')
runtime = (root/'tools/jfk-plan-runtime.js').read_text()
(root/'public/jfk-plan.js').write_text("import {samplePath, aircraftAt, standIntervals, gateConflicts, recoveryArrivalAt} from '/jfk-replay.mjs';\n"+prefix+runtime)
